#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
set +x
TOTAL_STAGES=3
root=$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")/.." && pwd)
reader="$HOME/.config/infisical/leer.py"
writer="$HOME/.config/infisical/cargar.py"
ENV_FILE=/dev/null
open_for_juanma() {
  python3 - "$1" <<'PYOPEN'
import shlex,subprocess,sys
url=sys.argv[1]
subprocess.run(['ssh','-o','BatchMode=yes','-o','ConnectTimeout=10','juanma@100.78.9.89',
                '/usr/bin/open '+shlex.quote(url)],check=True)
PYOPEN
}
case "${1:---dry-run}" in
  --dry-run)
    printf '%s\n' \
      'SECO: no abre navegador, no lee secretos, no despliega y no envía correos.' \
      'OPCIONAL, --images sha-<commit>: comprueba pull anónimo; solo pide a Juanma cambiar visibilidad si un paquete sigue privado.' \
      '   No requiere Giuli, no activa SMTP ni solicita token. Todo sigue en captura y BOOKING_MODE off.' \
      '1. Juanma: autorizar/publicar OAuth Google; ID y secret a RBLN /cal GOOGLE_API_CREDENTIALS.' \
      '   Automático en GO: sync a rbln-cal, SMTP Mailgun y dominio canónico; esperar deployments sanos.' \
      '2. Giuli leyendo su correo: solicitar reset de un uso/6 h ahora, crear su clave, comprobar que la inicial falla.' \
      '   Registrar rechazo explícito y logout; secrets-vault retira la inicial después, según T14e.' \
      '3. Giuli: conectar Google y elegir Pacientes; comprobar calendario destino y conflictos por API.' \
      'DNS se coordina aparte con el orquestador. BOOKING_MODE sigue off.'
    exit 0 ;;
  --images)
    [[ "${2:-}" =~ ^sha-[0-9a-f]{40}$ ]] || { printf '%s\n' 'Falta sha-<commit completo aprobado por CI>.' >&2; exit 2; }
    [[ -t 0 ]] || { printf '%s\n' 'La etapa de visibilidad requiere una terminal humana.' >&2; exit 1; }
    python3 "$root/deploy/check-public-image.py"
    if python3 "$root/deploy/check-public-pull.py" "$2"; then exit 0; fi
    TOTAL_STAGES=1
    banner 'RBLN Agenda · imágenes públicas, sin activar la agenda'
    stage 'Juanma: publicar los dos paquetes de GHCR'
    for app in web api; do
      open_for_juanma "https://github.com/users/juanmateixido/packages/container/rbln-cal-$app/settings"
      step "En rbln-cal-$app: Danger Zone → Change visibility → Public; confirmá el nombre del paquete si GitHub lo pide."
      pause "Cuando rbln-cal-$app sea público, presioná Enter."
    done
    python3 "$root/deploy/check-public-pull.py" "$2"
    note 'Verificados anónimamente manifest, config y acceso HEAD a todas las capas; sin descargar la imagen en bee.'
    note 'SMTP permanece en captura. BOOKING_MODE off. No se abrió ninguna sesión de Giuliana.'
    finish
    exit 0 ;;
  --go) ;;
  *) printf '%s\n' 'Uso: rbln/wizard-juanma.sh [--dry-run|--images sha-<commit>|--go]' >&2; exit 2 ;;
esac
[[ -t 0 ]] || { printf '%s\n' 'El GO requiere una terminal humana.' >&2; exit 1; }
confirm '¿Juanma dio GO y Giuliana está disponible para leer su correo y conectar Google ahora?' || exit 1
export CAL_GO_APPROVED=yes
# Prefer the project dependency; bee can reuse its existing standalone browser runtime.
if [[ -z "${PLAYWRIGHT_MODULE:-}" && -d "$HOME/.bun/install/cache/playwright-core@1.63.0@@@1" ]]; then
  export PLAYWRIGHT_MODULE="$HOME/.bun/install/cache/playwright-core@1.63.0@@@1"
fi
node -e 'require(process.env.PLAYWRIGHT_MODULE || "playwright")' >/dev/null
banner 'RBLN Agenda · GO con Juanma y Giuliana'

stage 'Juanma: app OAuth propia de Google'
open_for_juanma 'https://console.cloud.google.com/auth/overview'
step 'Seleccioná el proyecto propio de RBLN. Google Auth Platform → Branding: RBLN Agenda y dominio rebelion.training.'
step 'Audience: elegí el público aplicable; si es External, publicá In production para evitar tokens de prueba de 7 días.'
step 'Data Access: userinfo.profile, calendar.events y calendar.readonly; completá verificación si Google la exige.'
step 'APIs & Services → Library: Google Calendar API habilitada.'
step 'Clients → Create client → Web application. Origen: https://agenda.rebelion.training'
step 'Authorized redirect URI: https://agenda.rebelion.training/api/integrations/googlecalendar/callback'
note 'Infisical contiene un cliente de TXD/google-staff para otra app; no se reutiliza en RBLN. No se encontró gcloud en bee ni en el Mac.'
ask_secret CAL_GOOGLE_CLIENT_ID 'Client ID del cliente web:'
ask_secret CAL_GOOGLE_CLIENT_SECRET 'Client secret (entrada oculta):'
export CAL_GOOGLE_CLIENT_ID CAL_GOOGLE_CLIENT_SECRET
python3 - "$writer" <<'PYGO'
import json,os,subprocess,sys
client=os.environ['CAL_GOOGLE_CLIENT_ID'];secret=os.environ['CAL_GOOGLE_CLIENT_SECRET']
if not client.endswith('.apps.googleusercontent.com') or not secret:
    raise SystemExit('Credenciales OAuth inválidas; no se guardó nada')
value=json.dumps({'web':{'client_id':client,'client_secret':secret,'redirect_uris':[
    'https://agenda.rebelion.training/api/integrations/googlecalendar/callback']}})
subprocess.run(['python3',sys.argv[1],'RBLN','/cal','GOOGLE_API_CREDENTIALS'],input=value,text=True,check=True)
PYGO
unset CAL_GOOGLE_CLIENT_ID CAL_GOOGLE_CLIENT_SECRET
confirm '¿El cliente está publicado y el acceso requerido de Calendar está habilitado?' || exit 1
python3 "$root/scripts/rbln/go-activate.py"

stage 'Giuli: abrí el mail y creá tu clave'
step 'Abrí tu correo ahora. La solicitud se envía en este momento; el enlace se usa una sola vez y vence en 6 horas.'
step 'Elegí tu contraseña en la página de Cal. No la copies en esta terminal ni se la pases al agente.'
confirm '¿Giuli ya está leyendo su correo y lista para crear su clave ahora?' || exit 1
python3 "$reader" RBLN /cal NEXT_PUBLIC_WEBAPP_URL SMTP_MODE CAL_ADMIN_EMAIL CAL_ADMIN_INITIAL_PASSWORD -- \
  flock /tmp/bee-pesado.lock node "$root/scripts/rbln/go-check.cjs" request-reset
pause 'Giuli: abrí el mail, creá tu clave y guardala en tu gestor; después presioná Enter.'
python3 "$reader" RBLN /cal NEXT_PUBLIC_WEBAPP_URL SMTP_MODE CAL_ADMIN_EMAIL CAL_ADMIN_INITIAL_PASSWORD -- \
  flock /tmp/bee-pesado.lock node "$root/scripts/rbln/go-check.cjs" verify-reset
note 'La inicial ya no inicia sesión. Queda evidencia para secrets-vault; el wizard no borra la clave.'

stage 'Giuli: conectar Google Calendar y elegir Pacientes'
open_for_juanma 'https://agenda.rebelion.training/apps/google-calendar'
step 'Iniciá sesión con tu nueva clave, conectá tu cuenta Google y autorizá los permisos de Calendar.'
open_for_juanma 'https://agenda.rebelion.training/settings/my-account/calendars'
step 'Elegí Pacientes como calendario donde se crean las reservas y marcá los calendarios que bloquean disponibilidad.'
pause 'Cuando Pacientes esté seleccionado, presioná Enter para verificarlo automáticamente.'
python3 "$reader" RBLN /crm CAL_API_KEY -- \
  python3 "$reader" RBLN /cal NEXT_PUBLIC_WEBAPP_URL SMTP_MODE CAL_API_URL -- \
  node "$root/scripts/rbln/go-check.cjs" verify-calendar
note 'BOOKING_MODE permanece off. La activación del puente requiere el GO específico del orquestador.'
note 'Evidencia: rbln/evidence/agent-sessions.jsonl. Avisar a secrets-vault de la rotación para aplicar T14e.'
finish
